#!/usr/bin/env bash
# step101 — Batch 2: forgot password via verified WhatsApp or email. Adds
# /forgot + /reset (6-digit code, 30-min expiry, attempt cap), the views, the
# whatsapp.password_reset template, and restores the login "Forgot?" link.
# Idempotent; rolls back account.js + login.ejs.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step101-$TS
mkdir -p "$BAK/routes" "$BAK/views/account"
cp "$APP/routes/account.js" "$BAK/routes/account.js"
cp "$APP/views/account/login.ejs" "$BAK/views/account/login.ejs"
restore(){ echo "!! rollback"; cp "$BAK/routes/account.js" "$APP/routes/account.js"; cp "$BAK/views/account/login.ejs" "$APP/views/account/login.ejs"; rm -f "$APP/views/account/forgot.ejs" "$APP/views/account/reset.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> seed whatsapp.password_reset template"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
p.query("INSERT INTO wa_templates(key,body) VALUES('whatsapp.password_reset','\u{1F510} Your {{site_name}} password reset code is {{code}}. It expires in 30 minutes. If this was not you, ignore this message.') ON CONFLICT(key) DO NOTHING")
  .then(()=>{ console.log('   template ready'); return p.end(); }).catch(e=>{ console.error(e.message); p.end(); process.exit(1); });
NODE

echo "==> write account.js + views"
base64 -d > "$APP/routes/account.js" <<'B64'

B64
base64 -d > "$APP/views/account/login.ejs" <<'B64'

B64
base64 -d > "$APP/views/account/forgot.ejs" <<'B64'

B64
base64 -d > "$APP/views/account/reset.ejs" <<'B64'

B64

echo "==> node --check + ejs compile + restart"
node --check "$APP/routes/account.js"
node -e "const ejs=require('ejs'),fs=require('fs');['views/account/login.ejs','views/account/forgot.ejs','views/account/reset.ejs'].forEach(v=>{ejs.compile(fs.readFileSync('$APP/'+v,'utf8'),{filename:'$APP/'+v});});console.log('   views compile');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q 'Forgot password' <<<"$(curl -s -m 10 http://127.0.0.1:3900/forgot || true)" || { echo "!! /forgot not rendering"; false; }
grep -q 'Reset password' <<<"$(curl -s -m 10 http://127.0.0.1:3900/reset || true)" || { echo "!! /reset not rendering"; false; }
trap - ERR
echo "==> step101 OK — forgot/reset password via WhatsApp or email. Backup: $BAK"
